@Composable private fun Cover(song:Song?,edit:Edit?,size:Int=52,uri:String?=null) {
    val c=LocalContext.current
    var embedded by remember(song?.uri,edit?.cover) { mutableStateOf<ByteArray?>(null) }
    LaunchedEffect(song?.uri,edit?.cover) { if(song!=null && edit?.cover==null) embedded=Tools.embedded(c,song) }
    val model=uri ?: edit?.cover?.takeUnless { it=="-" } ?: embedded
    Box(Modifier.size(size.dp).clip(RoundedCornerShape(if(size>100)28.dp else 14.dp)).background(Brush.linearGradient(listOf(MaterialTheme.colorScheme.surfaceVariant,MaterialTheme.colorScheme.primary.copy(alpha=0.22f)))),contentAlignment=Alignment.Center) {
        Crossfade(targetState=model,animationSpec=tween(220),label="artwork") { artwork ->
            if(artwork!=null) AsyncImage(model=artwork,contentDescription="Carátula",modifier=Modifier.fillMaxSize(),contentScale=ContentScale.Crop) else Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){Icon(Icons.Default.MusicNote,"Sin carátula",tint=MaterialTheme.colorScheme.primary,modifier=Modifier.size((size/2).dp))}
        }
    }
}
@Composable private fun Head(title:String,sub:String="") { Column(Modifier.padding(vertical=12.dp)) { Text(title,style=MaterialTheme.typography.headlineMedium,fontWeight=FontWeight.Bold); if(sub.isNotBlank()) Text(sub,color=MaterialTheme.colorScheme.onSurfaceVariant,style=MaterialTheme.typography.bodyMedium) } }
@Composable private fun SongRow(s:Song,e:Edit?,onPlay:()->Unit,onMenu:()->Unit,selected:Boolean=false) {
    var expanded by remember(s.uri) { mutableStateOf(false) }
    ElevatedCard(Modifier.fillMaxWidth().padding(vertical=5.dp)) {
        Column {
            Row(Modifier.fillMaxWidth().padding(horizontal=9.dp,vertical=8.dp),verticalAlignment=Alignment.CenterVertically) {
                Cover(s,e,54)
                Column(Modifier.weight(1f).padding(horizontal=12.dp).clickable(onClick=onPlay)) {
                    Text(s.title,fontWeight=FontWeight.SemiBold,maxLines=1,overflow=TextOverflow.Ellipsis)
                    Text("${s.artist} • ${formatTime(s.duration)}",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant,maxLines=1,overflow=TextOverflow.Ellipsis)
                }
                if(selected || e?.favorite==true) Icon(if(selected) Icons.Default.CheckCircle else Icons.Default.Favorite,"Marcada",tint=MaterialTheme.colorScheme.primary)
                IconButton(onClick={expanded=!expanded}) { Icon(if(expanded) Icons.Default.KeyboardArrowUp else Icons.Default.KeyboardArrowDown,if(expanded)"Contraer" else "Mostrar detalles") }
            }
            AnimatedVisibility(expanded,enter=fadeIn()+expandVertically(),exit=fadeOut()+shrinkVertically()) {
                Column(Modifier.fillMaxWidth().padding(horizontal=12.dp).padding(bottom=12.dp)) {
                    HorizontalDivider()
                    Spacer(Modifier.height(10.dp))
                    Row(verticalAlignment=Alignment.CenterVertically) {
                        Cover(s,e,112)
                        Column(Modifier.weight(1f).padding(start=14.dp),verticalArrangement=Arrangement.spacedBy(5.dp)) {
                            Text("Carátula y detalles",style=MaterialTheme.typography.labelMedium,color=MaterialTheme.colorScheme.primary)
                            Text(s.title,fontWeight=FontWeight.Bold,style=MaterialTheme.typography.titleMedium)
                            Text("Artista: ${s.artist.ifBlank{"Desconocido"}}",style=MaterialTheme.typography.bodySmall)
                            Text("Álbum: ${s.album.ifBlank{"Sin álbum"}}",style=MaterialTheme.typography.bodySmall)
                            Text("Duración: ${formatTime(s.duration)}",style=MaterialTheme.typography.bodySmall,color=MaterialTheme.colorScheme.onSurfaceVariant)
                        }
                    }
                    Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.padding(top=10.dp)) {
                        Button(onClick=onPlay) { Icon(Icons.Default.PlayArrow,null);Text(" Reproducir") }
                        OutlinedButton(onClick=onMenu) { Icon(Icons.Default.MoreHoriz,null);Text(" Opciones") }
                    }
                }
            }
        }
    }
}
